CREATE TABLE requests (id INTEGER PRIMARY KEY, record TEXT NOT NULL, ts GENERATED ALWAYS AS (json_extract(record, '$.ts')) STORED,endpoint GENERATED ALWAYS AS (json_extract(record, '$.endpoint')) STORED,model GENERATED ALWAYS AS (json_extract(record, '$.model')) STORED,prompt_eval_count GENERATED ALWAYS AS (json_extract(record, '$.prompt_eval_count')) STORED,eval_count GENERATED ALWAYS AS (json_extract(record, '$.eval_count')) STORED,load_duration GENERATED ALWAYS AS (json_extract(record, '$.load_duration')) STORED,prompt_eval_duration GENERATED ALWAYS AS (json_extract(record, '$.prompt_eval_duration')) STORED,eval_duration GENERATED ALWAYS AS (json_extract(record, '$.eval_duration')) STORED,total_duration GENERATED ALWAYS AS (json_extract(record, '$.total_duration')) STORED,usage GENERATED ALWAYS AS (json_extract(record, '$.usage')) STORED,latency_ms GENERATED ALWAYS AS (json_extract(record, '$.latency_ms')) STORED,status GENERATED ALWAYS AS (json_extract(record, '$.status')) STORED,stream GENERATED ALWAYS AS (json_extract(record, '$.stream')) STORED,error GENERATED ALWAYS AS (json_extract(record, '$.error')) STORED,client_ip GENERATED ALWAYS AS (json_extract(record, '$.client_ip')) STORED,client_hostname GENERATED ALWAYS AS (json_extract(record, '$.client_hostname')) STORED);
CREATE INDEX requests_ts ON requests(ts);
CREATE INDEX requests_model_ts ON requests(model, ts);
CREATE TABLE gpu_samples (id INTEGER PRIMARY KEY, ts INTEGER NOT NULL, sample TEXT NOT NULL, "index" GENERATED ALWAYS AS (json_extract(sample, '$.index')) STORED,"memory_used_mib" GENERATED ALWAYS AS (json_extract(sample, '$.memory_used_mib')) STORED,"memory_total_mib" GENERATED ALWAYS AS (json_extract(sample, '$.memory_total_mib')) STORED,"utilization_percent" GENERATED ALWAYS AS (json_extract(sample, '$.utilization_percent')) STORED,"temperature_c" GENERATED ALWAYS AS (json_extract(sample, '$.temperature_c')) STORED,"power_w" GENERATED ALWAYS AS (json_extract(sample, '$.power_w')) STORED);
CREATE INDEX gpu_ts ON gpu_samples(ts);
